// Renamed from draw() to drawBootScreen() for clarity
void drawBootScreen(void) {
    tft.drawEllipse(119, 119, 120, 119, 0xFFFF);
    tft.setTextColor(0xE8EC);
    tft.setTextSize(2);
    tft.setFreeFont();
    tft.drawString("Sidequester V1.0", 24, 51);
    tft.drawBitmap(85, 15, image_FaceCharging_bits, 58, 28, 0xFFFF);
    tft.drawBitmap(80, 88, image_music_sound_wave_bits, 68, 64, 0xFFFF);
    tft.setTextColor(0x24BE);
    tft.drawString("Booting Up ....", 26, 167);
    tft.drawBitmap(19, 105, image_music_radio_broadcast_bits, 30, 32, 0xFAA4);
    tft.drawBitmap(177, 104, image_location_map_bits, 30, 32, 0x3A96);
}

// Initialize the boot screen display
void initBootScreen() {
    tft.init();
    tft.setRotation(1); // Landscape mode
    tft.fillScreen(COLOR_BG);
}

